"use client";
import { useState } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { IconDefinition } from "@fortawesome/fontawesome-svg-core";
import {
  faTableColumns,
  faCalendarCheck,
  faWallet,
  faUserGear,
  faSuitcaseRolling,
  faStar,
  faBars,
  faXmark,
} from "@fortawesome/free-solid-svg-icons";

type NavItem = {
  href: string;
  label: string;
  icon: IconDefinition;
};


export default function Menu() {
  const [open, setOpen] = useState(false);
  const pathname = usePathname();


  // Robust active detection: exact match for the overview root, prefix match
  // for every sub-section.
  const isActive = (href: string) =>
    href === "/profile" ? pathname === "/profile" : pathname.startsWith(href);

  const items: NavItem[] = [
    { href: "/profile", label: "Overview", icon: faTableColumns },
    { href: "/profile/bookings-enquiries", label: "Bookings & Enquiries", icon: faCalendarCheck },
    { href: "/profile/credit-details", label: "Credit Details", icon: faWallet },
    {
      href: "/profile/personal-information",
      label: "Personal Information",
      icon: faUserGear,
    },
    { href: "/profile/travel-preferences", label: "Travel Preferences", icon: faSuitcaseRolling },
    { href: "/profile/reviews", label: "Reviews", icon: faStar },
  ];

  // Ana site yalnız customer: rol bazlı madde yok, hepsi görünür.
  const visibleItems = items;

  return (
    <nav className="tw-font-display">
      {/* Mobile toggle — replaces Bootstrap data-bs collapse */}
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="md:tw-hidden tw-mb-3 tw-flex tw-w-full tw-items-center tw-justify-between tw-rounded-xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-px-4 tw-py-3 tw-text-sm tw-font-semibold tw-text-[#14101c]"
      >
        <span className="tw-flex tw-items-center tw-gap-2.5">
          <FontAwesomeIcon icon={open ? faXmark : faBars} className="tw-text-[#854ec9]" />
          Profile Menu
        </span>
      </button>

      <div
        className={`${open ? "tw-block" : "tw-hidden"} md:tw-block tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-2 tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]`}
      >
        <ul className="tw-m-0 tw-flex tw-list-none tw-flex-col tw-gap-1 tw-p-0">
          {visibleItems.map((item) => {
            const active = isActive(item.href);
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  onClick={() => setOpen(false)}
                  className={`tw-flex tw-items-center tw-gap-3 tw-rounded-xl tw-px-3.5 tw-py-2.5 tw-text-sm tw-font-medium tw-no-underline tw-transition-colors tw-duration-200 ${
                    active
                      ? "tw-bg-[#f4eefc] tw-font-semibold tw-text-[#6a3da4]"
                      : "tw-text-[#3f3a4d] hover:tw-bg-[#f6f4fa] hover:tw-text-[#14101c]"
                  }`}
                >
                  <FontAwesomeIcon
                    icon={item.icon}
                    className={`tw-w-5 tw-text-center ${active ? "tw-text-[#854ec9]" : "tw-text-[#9b95a8]"}`}
                  />
                  {item.label}
                </Link>
              </li>
            );
          })}
        </ul>
      </div>
    </nav>
  );
}
