import { getMe } from "@/app/actions/auth";
import { forceLogout, hasAuthCookie, haltForLogout, isLoggingOut } from "@/lib/authSession";

/**
 * Giriş yapmış kullanıcı profili. Artık apiv3 `/auth/me`'ye bağlanan `getMe` server
 * action'ına delege eder; token cookie'den sunucuda okunur, bu yüzden `token` argümanı
 * yok sayılır (geriye dönük imza uyumu için korunuyor). Tüm tüketiciler client bileşeni.
 *
 * `getMe` sunucuda çalıştığı için geçersiz/süresi dolmuş token'da apiv3 401'i orada
 * yutulur (null döner) — tarayıcıdaki global fetch interceptor bu yola ulaşamaz. Bu
 * yüzden auto-logout'u BURADA (client'ta) tamamlıyoruz: kullanıcı kendini login'li
 * sanıyor (cookie var) ama `/auth/me` null döndüyse oturum zorla kapatılır. Aksi halde
 * eskiden olduğu gibi "Failed to fetch data" fırlatıp ekran çökerdi ama header diğer
 * cookie'lerden hâlâ login görünürdü.
 */
export default async function getUserDetail(_args?: { token?: unknown }) {
  const user = await getMe();
  if (!user) {
    // Login'li görünüp (cookie var) /auth/me null döndüyse token geçersiz → sessiz
    // logout. `getMe` sunucuda çalıştığından 401 orada yutulur; fetch interceptor bu
    // yola ulaşamaz, bu yüzden burada kapatıyoruz. HATA FIRLATMA (haltForLogout) →
    // "Failed to fetch data" Sentry'e düşmez, overlay çakmaz; reload temizler.
    // hasAuthCookie: bu istek logout'u tetikler. isLoggingOut: başka bir 401 zaten
    // logout'u başlatıp cookie'leri sildi (yarış) → yine sessiz kal, throw etme.
    if (hasAuthCookie() || isLoggingOut()) {
      forceLogout();
      return haltForLogout();
    }
    throw new Error("Failed to fetch data");
  }
  return user;
}
